type Meters float64
type Feet float64

func (m Meters) Feet() Feet    { return Feet(m * 3.280839895) }
func (f Feet) Meters() Meters  { return Meters(f / 3.280839895) }
func (m Meters) String() string { return strconv.FormatFloat(float64(m), 'f', -1, 64) + " m" }

var span Meters = 3_000
total := span + Meters(500)          // same unit: plain arithmetic
fmt.Println(total.Feet())            // 11482.939...
_ = total + Meters(Feet(1))          // compile error: mismatched types

